_TAPES = None
_OPP_TYPE = {0: "hozuma", 1: "hozuma"}
# Diagnostic hook used by the local replay harness.  It is intentionally None
# for Kaggle submissions, so the normal public-observation router remains the
# default behavior.
_FORCED_ROUTE = None

_SELLABLE = [
    "MELON", "STRAWBERRY", "TOMATO", "CARROT", "WHEAT",
    "WOOL", "MILK", "EGG", "FERTILIZER"
]

def _load_tapes():
    global _TAPES
    if _TAPES is None:
        raw = zlib.decompress(base64.b85decode(_TAPES_COMPRESSED.encode("ascii"))).decode("utf-8")
        _TAPES = json.loads(raw)

def _pass_action(obs):
    p = obs.get("player", 0) if isinstance(obs, dict) else getattr(obs, "player", 0)
    farms = obs.get("farms", []) if isinstance(obs, dict) else getattr(obs, "farms", [])
    h_count = len(farms[p].get("hands", [])) if p < len(farms) else 0
    return {"farmer": ["PASS"], "hands": [["PASS"] for _ in range(h_count)], "market": []}

def agent(obs, config=None):
    """Grandmaster agent entrypoint."""
    del config
    _load_tapes()
    
    player = obs.get("player", 0) if isinstance(obs, dict) else getattr(obs, "player", 0)
    step = obs.get("step", 0) if isinstance(obs, dict) else getattr(obs, "step", 0)
    
    if step == 0:
        _OPP_TYPE[player] = "hozuma"
        
    opp = 1 - player
    farms = obs.get("farms", []) if isinstance(obs, dict) else getattr(obs, "farms", [])
    opp_farm = farms[opp] if opp < len(farms) else {}
    
    # Step 1: Detect opponent archetype
    if step in (1, 2):
        try:
            opp_money = opp_farm.get("money", 3000)
            opp_tiles = opp_farm.get("tiles", [])
            
            # Check if opponent built pasture or bought carrot (Subramanya).
            has_carrot = False
            opp_pastures = 0
            for row in opp_tiles:
                if isinstance(row, list):
                    for tile in row:
                        if isinstance(tile, dict):
                            if tile.get("type") == "PASTURE":
                                opp_pastures += 1
                            if tile.get("crop") == "CARROT":
                                has_carrot = True

            if opp_pastures >= 1 and (has_carrot or opp_money > 100):
                # Subramanya pasture opening -> counter with QQ Farming.
                _OPP_TYPE[player] = "qq"
            elif opp_money < 1500 and step == 1:
                # Strawberry opening (Tetsuya/Hozuma) -> start with hozuma
                _OPP_TYPE[player] = "hozuma"
            else:
                # Dahoui peer (OceanMix, Crop, QQ, Driz, Iulian, etc.) -> Hozuma master route
                _OPP_TYPE[player] = "hozuma"
        except Exception:
            _OPP_TYPE[player] = "hozuma"
            
    # Step 73: Distinguish Tetsuya (money < 80) from Hozuma (money >= 80)
    if step == 73 and _OPP_TYPE.get(player) in ("hozuma", "tetsuya"):
        try:
            opp_money = opp_farm.get("money", 100)
            if opp_money < 80:
                _OPP_TYPE[player] = "tetsuya"
            else:
                _OPP_TYPE[player] = "hozuma"
        except Exception:
            pass

    if _FORCED_ROUTE in _TAPES:
        _OPP_TYPE[player] = _FORCED_ROUTE
            
    # Retrieve base action
    tape_key = _OPP_TYPE.get(player, "hozuma")
    tape = _TAPES.get(tape_key, _TAPES["hozuma"])
    
    if step < len(tape):
        act = copy.deepcopy(tape[step])
        
        # Align hands
        my_farm = farms[player] if player < len(farms) else {}
        num_hands = len(my_farm.get("hands", []))
        hands_act = list(act.get("hands") or [])
        if len(hands_act) < num_hands:
            hands_act.extend([["PASS"] for _ in range(num_hands - len(hands_act))])
        act["hands"] = hands_act[:num_hands]
        
        # Step 718 Terminal Shed Sweep:
        # Liquidate all remaining produce in private shed
        if step == 718:
            private = obs.get("private", {}) if isinstance(obs, dict) else getattr(obs, "private", {})
            shed = private.get("shed", {})
            curr_market = list(act.get("market") or [])
            already_selling = set()
            for order in curr_market:
                if len(order) >= 2 and order[0] == "SELL":
                    already_selling.add(order[1])
                    
            for item in _SELLABLE:
                qty = shed.get(item, 0)
                if qty > 0 and item not in already_selling and len(curr_market) < 10:
                    curr_market.append(["SELL", item, int(qty)])
                    
            act["market"] = curr_market[:10]
            
        return act
        
    return _pass_action(obs)

main = agent
